package com.flowerconnect.vendor.controller;

import com.flowerconnect.catalog.domain.Product.ProductStatus;
import com.flowerconnect.catalog.dto.ProductPageResponse;
import com.flowerconnect.catalog.dto.ProductRequest;
import com.flowerconnect.catalog.dto.ProductResponse;
import com.flowerconnect.catalog.service.ProductService;
import com.flowerconnect.vendor.security.RequiresApprovedVendor;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Positive;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

/**
 * Vendor-scoped product catalog (plan task 3.5).
 *
 * <p>Base path is {@code /api/v1/vendors/products}, deliberately inside the existing
 * {@code /api/v1/vendors/**} namespace rather than a new {@code /vendor/} prefix, so the
 * {@code hasRole("FLORIST")} rule in {@code SecurityConfig} already applies and the two
 * authorization layers stay in their documented order (D-13): the namespace answers "is
 * this a vendor account?" and {@link RequiresApprovedVendor} answers "may this vendor
 * transact?".
 *
 * <p>The vendor is resolved from the JWT subject on every call. No route accepts a
 * vendor identifier, so cross-vendor access is not expressible in the request at all;
 * a product that belongs to another vendor is a 403 and one that does not exist is a
 * 404.
 *
 * <p>Removal is soft — {@code PATCH /{productId}/deactivate} moves the product to
 * {@code INACTIVE} and leaves its row, images and inventory in place so historical
 * stock movements remain readable. A vendor can bring the product back through
 * {@code PUT /{productId}}.
 *
 * <p>{@code status} on the request body is optional and defaults to {@code DRAFT}: a
 * product is invisible to the storefront until the vendor activates it. No transition
 * table is enforced between the four lifecycle values — the plan defines none, and an
 * invented one would block a vendor correcting their own mistake (the reasoning behind
 * D-14 for user status).
 */
@Slf4j
@Validated
@Tag(name = "Vendor catalog", description = "Product CRUD for the authenticated vendor")
@RequiresApprovedVendor
@RestController
@RequestMapping("/api/v1/vendors/products")
@RequiredArgsConstructor
public class VendorProductController {

    private final ProductService productService;

    @Operation(summary = "Create a product",
            description = "Creates a product owned by the authenticated vendor together with its "
                    + "inventory row at quantity zero. The slug is generated by the server from the "
                    + "name with a collision-safe suffix and cannot be supplied by the client. "
                    + "Requires an APPROVED vendor profile.")
    @ApiResponses({
            @ApiResponse(responseCode = "201", description = "Product created"),
            @ApiResponse(responseCode = "400", description = "Validation failed, or the category is unknown or inactive"),
            @ApiResponse(responseCode = "403", description = "Vendor profile is not APPROVED (VENDOR_NOT_APPROVED)")
    })
    @PostMapping
    public ResponseEntity<ProductResponse> createProduct(
            Authentication authentication,
            @Valid @RequestBody ProductRequest request) {
        String vendorEmail = authentication.getName();
        ProductResponse response = productService.create(vendorEmail, request);
        log.info("Created product {} for vendor {}", response.getId(), vendorEmail);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @Operation(summary = "List the authenticated vendor's products",
            description = "Returns one page of the vendor's own products, newest first. Every filter is "
                    + "optional and omitted filters do not narrow the result. Page size is clamped to "
                    + "1..100 by the service.")
    @GetMapping
    public ResponseEntity<ProductPageResponse> listProducts(
            Authentication authentication,
            @Parameter(description = "Exact lifecycle status to match")
            @RequestParam(required = false) ProductStatus status,
            @Parameter(description = "Restrict to one category id")
            @RequestParam(required = false) @Positive Long categoryId,
            @Parameter(description = "Case-insensitive partial match on the product name")
            @RequestParam(required = false) String name,
            @RequestParam(defaultValue = "0") @Min(0) int page,
            @RequestParam(defaultValue = "20") @Min(1) @Max(100) int size) {

        String vendorEmail = authentication.getName();
        return ResponseEntity.ok(productService.list(vendorEmail, status, categoryId, name, page, size));
    }

    @Operation(summary = "Read one of the vendor's products",
            description = "Returns a single product owned by the authenticated vendor.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Product found"),
            @ApiResponse(responseCode = "403", description = "Product belongs to another vendor, or the profile is not APPROVED"),
            @ApiResponse(responseCode = "404", description = "No such product")
    })
    @GetMapping("/{productId}")
    public ResponseEntity<ProductResponse> getProduct(
            Authentication authentication,
            @PathVariable @Positive(message = "Product id must be positive") Long productId) {
        return ResponseEntity.ok(productService.getByIdForVendor(authentication.getName(), productId));
    }

    @Operation(summary = "Update a product",
            description = "Replaces the editable fields of a product the vendor owns. A changed name "
                    + "regenerates the slug with the same collision-safe rule used on create. Omitting "
                    + "status leaves the stored status untouched.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Product updated"),
            @ApiResponse(responseCode = "400", description = "Validation failed, or the category is unknown or inactive"),
            @ApiResponse(responseCode = "403", description = "Product belongs to another vendor, or the profile is not APPROVED"),
            @ApiResponse(responseCode = "404", description = "No such product")
    })
    @PutMapping("/{productId}")
    public ResponseEntity<ProductResponse> updateProduct(
            Authentication authentication,
            @PathVariable @Positive(message = "Product id must be positive") Long productId,
            @Valid @RequestBody ProductRequest request) {
        return ResponseEntity.ok(productService.update(authentication.getName(), productId, request));
    }

    @Operation(summary = "Deactivate a product (soft delete)",
            description = "Moves the product to INACTIVE. Nothing is physically removed: the row, its "
                    + "images and its inventory stay in place so historical stock movements remain "
                    + "readable. Repeating the call on an already-inactive product is a no-op.")
    @ApiResponses({
            @ApiResponse(responseCode = "204", description = "Product deactivated"),
            @ApiResponse(responseCode = "403", description = "Product belongs to another vendor, or the profile is not APPROVED"),
            @ApiResponse(responseCode = "404", description = "No such product")
    })
    @PatchMapping("/{productId}/deactivate")
    public ResponseEntity<Void> deactivateProduct(
            Authentication authentication,
            @PathVariable @Positive(message = "Product id must be positive") Long productId) {
        productService.deactivate(authentication.getName(), productId);
        return ResponseEntity.noContent().build();
    }
}